import itertools
import random

def check_girth(edges, n, min_girth=7):
    """Check if graph has girth at least min_girth."""
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS to find shortest cycle through start
        visited = {start: -1}
        queue = [(start, -1, 0)]  # (vertex, parent, distance)
        while queue:
            v, parent, dist = queue.pop(0)
            for neighbor in adj[v]:
                if neighbor not in visited:
                    visited[neighbor] = v
                    queue.append((neighbor, v, dist + 1))
                elif neighbor != parent and visited[neighbor] != v:
                    # Found a cycle
                    cycle_len = dist + 1 + (dist if visited[neighbor] == start else 0)
                    # Actually need to compute cycle length properly
                    pass

    # Better approach: check for cycles of length 3, 4, 5, 6
    # Check for triangles (3-cycles)
    edge_set = set()
    for u, v in edges:
        edge_set.add((min(u,v), max(u,v)))

    for u in range(n):
        neighbors_u = [v for v in range(n) if (min(u,v), max(u,v)) in edge_set]
        for i in range(len(neighbors_u)):
            for j in range(i+1, len(neighbors_u)):
                v, w = neighbors_u[i], neighbors_u[j]
                if (min(v,w), max(v,w)) in edge_set:
                    return False  # Triangle found

    # Check for 4-cycles
    for u in range(n):
        neighbors_u = [v for v in range(n) if (min(u,v), max(u,v)) in edge_set]
        for i in range(len(neighbors_u)):
            for j in range(i+1, len(neighbors_u)):
                v, w = neighbors_u[i], neighbors_u[j]
                # Check if v and w have a common neighbor other than u
                neighbors_v = [x for x in range(n) if (min(v,x), max(v,x)) in edge_set and x != u]
                for x in neighbors_v:
                    if (min(w,x), max(w,x)) in edge_set:
                        return False  # 4-cycle found

    # For 5-cycles and 6-cycles, use BFS
    for start in range(n):
        # BFS to find shortest cycle
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        while queue:
            v = queue.pop(0)
            for neighbor in range(n):
                if (min(v, neighbor), max(v, neighbor)) in edge_set:
                    if neighbor not in dist:
                        dist[neighbor] = dist[v] + 1
                        parent[neighbor] = v
                        queue.append(neighbor)
                    elif neighbor != parent[v]:
                        cycle_len = dist[v] + dist[neighbor] + 1
                        if cycle_len < min_girth:
                            return False

    return True

def is_k_colorable(edges, n, k):
    """Check if graph is k-colorable using backtracking."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for neighbor in adj[v]:
                if colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

