import itertools

def verify_graph(edges, n, min_girth=7, max_colors=4):
    """Comprehensive verification of graph properties."""
    # Build adjacency
    adj = [[] for _ in range(n)]
    edge_set = set()
    for u, v in edges:
        assert 0 <= u < v < n, f"Invalid edge ({u}, {v})"
        adj[u].append(v)
        adj[v].append(u)
        edge_set.add((u, v))

    print(f"Number of vertices: {n}")
    print(f"Number of edges: {len(edges)}")

    # Check for cycles of length 3, 4, 5, 6
    # Check triangles
    for u in range(n):
        for v in adj[u]:
            for w in adj[v]:
                if w > u and (min(u, w), max(u, w)) in edge_set:
                    print(f"Triangle found: {u}-{v}-{w}")
                    return False

    # Check 4-cycles: u-v-w-x-u
    for u in range(n):
        for v in adj[u]:
            for w in adj[v]:
                if w == u:
                    continue
                for x in adj[w]:
                    if x == v:
                        continue
                    if (min(u, x), max(u, x)) in edge_set:
                        print(f"4-cycle found: {u}-{v}-{w}-{x}")
                        return False

    # Check 5-cycles using BFS
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        while queue:
            v = queue.pop(0)
            for neighbor in adj[v]:
                if neighbor not in dist:
                    dist[neighbor] = dist[v] + 1
                    parent[neighbor] = v
                    queue.append(neighbor)
                elif neighbor != parent[v]:
                    cycle_len = dist[v] + dist[neighbor] + 1
                    if cycle_len < min_girth:
                        print(f"Cycle of length {cycle_len} found starting from {start}")
                        return False

    print(f"Girth >= {min_girth}: PASSED")

    # Check 4-colorability
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(max_colors):
            valid = True
            for neighbor in adj[v]:
                if colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    if backtrack(0):
        print(f"4-colorable: PASSED")
        print(f"Coloring: {colors}")
        return True
    else:
        print(f"4-colorable: FAILED")
        return False

